function Resolve-Safe([string]$Path,[string]$Description,[switch]$Exists){$full=if([IO.Path]::IsPathRooted($Path)){[IO.Path]::GetFullPath($Path)}else{[IO.Path]::GetFullPath((Join-Path $repo $Path))};$prefix=$repo.TrimEnd('\')+'\';if(-not$full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw "$Description escapes repository."};$current=$repo;foreach($part in @($full.Substring($prefix.Length).Split('\')|Where-Object{$_.Length})){$current=Join-Path $current $part;if((Test-Path -LiteralPath $current)-and((Get-Item -LiteralPath $current -Force).Attributes-band[IO.FileAttributes]::ReparsePoint)){throw "$Description traverses a reparse point."}};if($Exists-and-not(Test-Path -LiteralPath $full)){throw "$Description is missing."};$full}
function Assert-NoReparse([string]$Root){foreach($item in @(Get-ChildItem -LiteralPath $Root -Recurse -Force)){if($item.Attributes-band[IO.FileAttributes]::ReparsePoint){throw 'Evidence contains a reparse point.'}}}
function Get-Tree([string]$Root){$entries=@();$bytes=0L;foreach($item in @(Get-ChildItem -LiteralPath $Root -Recurse -Force|Sort-Object FullName)){$rel=$item.FullName.Substring($Root.Length).TrimStart('\').Replace('\','/');if($rel-ceq'result.json'){continue};if($item.PSIsContainer){$entries+=[ordered]@{kind='directory';path=$rel}}else{$bytes+=$item.Length;$entries+=[ordered]@{kind='file';path=$rel;bytes=$item.Length;sha256=(Get-FileHash -LiteralPath $item.FullName -Algorithm SHA256).Hash}}};$json=ConvertTo-Json @($entries)-Compress -Depth 4;$sha=[Security.Cryptography.SHA256]::Create();try{$hash=-join($sha.ComputeHash($utf8.GetBytes($json))|ForEach-Object{$_.ToString('X2')})}finally{$sha.Dispose()};[ordered]@{sha256=$hash;files=@($entries|Where-Object{$_.kind-ceq'file'}).Count;directories=@($entries|Where-Object{$_.kind-ceq'directory'}).Count;bytes=$bytes}}
function Get-Logs([string]$Root){$files=@(Get-ChildItem -LiteralPath $Root -File -Filter 'mcla*.log');if($files.Count-lt1-or$files.Count-gt31){throw 'Runtime-log count is invalid.'};$current=@($files|Where-Object{$_.Name-ceq'mcla.log'});if($current.Count-ne1){throw 'Current runtime log missing.'};$rot=@();foreach($file in @($files|Where-Object{$_.Name-cne'mcla.log'})){$match=[regex]::Match($file.Name,'^mcla\.([1-9][0-9]*)\.log$');if(-not$match.Success){throw 'Malformed runtime-log rotation.'};$rot+=[pscustomobject]@{index=[int]$match.Groups[1].Value;file=$file}};$indices=@($rot|ForEach-Object{$_.index}|Sort-Object);for($i=0;$i-lt$indices.Count;$i++){if($indices[$i]-ne$i+1){throw 'Runtime-log rotation gap.'}};$ordered=@($rot|Sort-Object index -Descending|ForEach-Object{$_.file})+$current[0];$text='';$manifest=@();$bytes=0L;foreach($file in $ordered){$bytes+=$file.Length;if($bytes-gt268435456){throw 'Runtime logs exceed 256 MiB.'};$text+=[IO.File]::ReadAllText($file.FullName)+"`n";$manifest+=[ordered]@{name=$file.Name;bytes=$file.Length;sha256=(Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash}};[pscustomobject]@{text=$text;manifest=@($manifest);bytes=$bytes}}
function One([string]$Text,[string]$Pattern,[string]$Name){$matches=[regex]::Matches($Text,$Pattern);if($matches.Count-ne1){throw "$Name count is $($matches.Count)."};$matches[0]}
function Read-Bmp([string]$Path,[string]$Name){$file=Resolve-Safe $Path $Name -Exists;$bytes=[IO.File]::ReadAllBytes($file);if($bytes.Length-ne3686454-or$bytes[0]-ne0x42-or$bytes[1]-ne0x4D-or[BitConverter]::ToInt32($bytes,18)-ne1280-or[Math]::Abs([BitConverter]::ToInt32($bytes,22))-ne720-or[BitConverter]::ToUInt16($bytes,28)-ne32){throw "$Name is not the exact 1280x720x32 BMP shape."};[ordered]@{sha256=(Get-FileHash -LiteralPath $file -Algorithm SHA256).Hash;bytes=$bytes.Length}}
function Assert-StaticContract{
  $source=[IO.File]::ReadAllText((Join-Path $repo 'src/mcla_app.cpp'));foreach($needle in @('mcla_race_system_probe','Lifecycle::kInitOnly','kRaceDescriptionTypeAddress = 0x822C9230','kRaceDescriptionSubtypeAddress = 0x822C9270','kRaceDescriptionCopZonesAddress = 0x822C92B0','kCheckpointListCountAddress = 0x82267528','kCheckpointHitAddress = 0x82263930','kRaceFinishAddress = 0x82256BE0','kRaceResultAddress = 0x821FBB40','RaceDescriptionTypeProbe','CheckpointListCountProbe','RaceFinishProbe','MCLA_RACE_SYSTEM_CONFIG v=1','MCLA_RACE_SYSTEM_READY v=1','MCLA_RACE_SYSTEM_FRAME v=1 phase={} width={} height={} ','MCLA_RACE_SYSTEM_SUMMARY v=1 status={} frames={} ','kRaceSystemDetailCapacity = 32','race_system_audit_enabled = false')){if(-not$source.Contains($needle)){throw "Race-system source contract is missing '$needle'."}}
