function Read-Prior([string]$Relative,[string]$Hash,[string]$Decision){$path=Resolve-Safe $Relative 'Prior evidence' -Exists;if((Get-FileHash $path -Algorithm SHA256).Hash-cne$Hash){throw 'Prior evidence hash drifted.'};$record=Get-Content $path -Raw|ConvertFrom-Json;if($record.decision-cne$Decision){throw 'Prior evidence decision drifted.'};[ordered]@{sha256=$Hash;decision=$Decision}}
function Get-Lifecycle([string]$Cycle){$logs=Get-Logs $Cycle;$text=$logs.text;foreach($bad in @('[FATAL]','Assertion failed','PPC_UNIMPLEMENTED','Guest crash','DXGI_ERROR_DEVICE_REMOVED','unregistered guest function')){if($text.Contains($bad)){throw "Lifecycle banned marker '$bad'."}};$frame=One $text 'MCLA graphics: nontrivial guest frame captured 1280x720' 'Lifecycle frame';$close=One $text 'Window closing, shutting down\.\.\.' 'Lifecycle close';$complete=One $text 'Execution complete' 'Lifecycle complete';$hard=One $text 'Title terminated; hard-exiting process\.' 'Lifecycle hard exit';if(-not($frame.Index-lt$close.Index-and$close.Index-lt$complete.Index-and$complete.Index-lt$hard.Index)){throw 'Lifecycle chronology is invalid.'};[ordered]@{controlled_exit=$true;runtime_logs=@($logs.manifest);runtime_log_bytes=$logs.bytes}}
