  $signin=One $text 'XAM_USER_SIGNIN_CONFIG v=1 state=2 mode=online-compatible' 'Sign-in config';$launch=One $text 'KernelState: Preparing module launch\.\.\.' 'Launch';$config=One $text 'MCLA_RACE_SYSTEM_CONFIG v=1 enabled=1 desc_type=822C9230 desc_subtype=822C9270 cop_zones=822C92B0 checkpoint_count=82267528 checkpoint_hit=82263930 finish=82256BE0 result=821FBB40 detail_cap=32' 'Race config';$ready=One $text 'MCLA_RACE_SYSTEM_READY v=1 phases=start,rewards external_close_required=1' 'Ready';$frames=[regex]::Matches($text,'MCLA_RACE_SYSTEM_FRAME v=1 phase=(start|rewards) width=1280 height=720 present_seq=([1-9][0-9]*) status=PASS');if($frames.Count-ne2-or$frames[0].Groups[1].Value-cne'start'-or$frames[1].Groups[1].Value-cne'rewards'-or[int64]$frames[1].Groups[2].Value-le[int64]$frames[0].Groups[2].Value){throw 'Frame identity/order is invalid.'}
